(3394218, 472023, 46663, '<td valign="top">Great setup and perfectly fits the challenge.  Wow!</td>', 'Great setup and perfectly fits the challenge.  Wow!', '2007-02-22 14:49:34.000000', NULL, 1),
(3394220, 472599, 66597, '<td valign="top">Pretty funny. I especially like the pin stuck in the teddy bear''s crotch. Ouch!</td>', 'Pretty funny. I especially like the pin stuck in the teddy bear''s crotch. Ouch!', '2007-02-22 14:50:09.000000', NULL, 1),
