(3394223, 472058, 46663, '<td valign="top">I love this photo - it speaks volumes and fits the challenge perfectly.</td>', 'I love this photo - it speaks volumes and fits the challenge perfectly.', '2007-02-22 14:50:18.000000', NULL, 1),
(3394225, 472585, 66597, '<td valign="top">Although I''m not sure the realization quite works here, this is an excellent, very creative idea.</td>', 'Although I''m not sure the realization quite works here, this is an excellent, very creative idea.', '2007-02-22 14:50:59.000000', NULL, 1),
(3394227, 472006, 71951, '<td valign="top">good concept</td>', 'good concept', '2007-02-22 14:51:10.000000', NULL, 1),
(3394228, 472664, 46663, '<td valign="top">Scary imagery.  Well taken and a great idea for this challenge.</td>', 'Scary imagery.  Well taken and a great idea for this challenge.', '2007-02-22 14:51:12.000000', NULL, 1),
(3394230, 471117, 66597, '<td valign="top">Really nice idea, shows the emotion well. Would like to see a little richer lighting - took me a minute to see the foot.</td>', 'Really nice idea, shows the emotion well. Would like to see a little richer lighting - took me a minute to see the foot.', '2007-02-22 14:51:39.000000', NULL, 1),
(3394231, 472356, 46663, '<td valign="top">The title says it all - great photograph.  This image fits the challenge with and without the title.  Good job.</td>', 'The title says it all - great photograph.  This image fits the challenge with and without the title.  Good job.', '2007-02-22 14:51:59.000000', NULL, 1),
(3394233, 472291, 66597, '<td valign="top">Funny expression :-) Don''t we all have those 1''s and 2''s - luckily I won''t be giving you one of those troll scores for this photo.</td>', 'Funny expression :-) Don''t we all have those 1''s and 2''s - luckily I won''t be giving you one of those troll scores for this photo.', '2007-02-22 14:52:26.000000', NULL, 1),
(3394234, 472419, 71951, '<td valign="top">Nice photo, great subject</td>', 'Nice photo, great subject', '2007-02-22 14:52:47.000000', NULL, 1),
(3394236, 471488, 46663, '<td valign="top">Excellent photograph - clarity and motion all at the same time.  Although the photograph itself doesn''t speak to Hate, the title is a perfect match and makes the submission perfect for this challenge.  Nice job!</td>', 'Excellent photograph - clarity and motion all at the same time.  Although the photograph itself doesn''t speak to Hate, the title is a perfect match and makes the submission perfect for this challenge.  Nice job!', '2007-02-22 14:53:22.000000', NULL, 1),
(3394238, 469096, 71951, '<td valign="top">Very nice photo, I like the editing</td>', 'Very nice photo, I like the editing', '2007-02-22 14:53:30.000000', NULL, 1),
(3394242, 472342, 66597, '<td valign="top">Looks like a real love-hate relationship going on here. Makes me want to know more, which is a mark of a good photo in my book.</td>', 'Looks like a real love-hate relationship going on here. Makes me want to know more, which is a mark of a good photo in my book.', '2007-02-22 14:53:52.000000', NULL, 1),
(3394245, 472342, 71951, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2007-02-22 14:54:21.000000', NULL, 1),
(3394246, 472599, 46663, '<td valign="top">Ouch!  Good job on the title and perfect capture.  The DOF is great and I love how the colors really are muted except for the red.  Nice job!</td>', 'Ouch!  Good job on the title and perfect capture.  The DOF is great and I love how the colors really are muted except for the red.  Nice job!', '2007-02-22 14:54:33.000000', NULL, 1),
(3394249, 469148, 66597, '<td valign="top">Interesting photo open to many different interpretations.</td>', 'Interesting photo open to many different interpretations.', '2007-02-22 14:55:42.000000', NULL, 1),
(3394266, 471362, 66597, '<td valign="top">Wow, this is a powerful and disturbing image. So far, in a whole different league from the other photos. 10.</td>', 'Wow, this is a powerful and disturbing image. So far, in a whole different league from the other photos. 10.', '2007-02-22 15:01:41.000000', NULL, 1),
(3394274, 470421, 66597, '<td valign="top">Hi Bob, I think I''ve seen this devil before! Much better capture this time. The lighting is nice and the devil really stands out.</td>', 'Hi Bob, I think I''ve seen this devil before! Much better capture this time. The lighting is nice and the devil really stands out.', '2007-02-22 15:03:23.000000', NULL, 1),
(3394277, 470313, 66597, '<td valign="top">Great photo, though it seems a little shoehorned in.</td>', 'Great photo, though it seems a little shoehorned in.', '2007-02-22 15:03:53.000000', NULL, 1),
(3394279, 472581, 66597, '<td valign="top">Oooooo, very creative.</td>', 'Oooooo, very creative.', '2007-02-22 15:05:23.000000', NULL, 1),
(3394282, 472464, 66597, '<td valign="top">Excellent entry, and great title.</td>', 'Excellent entry, and great title.', '2007-02-22 15:06:06.000000', NULL, 1),
(3394283, 472291, 22479, '<td valign="top">I hope this one will do better than your "Life Returns!" entry. Good luck, Delta_6.</td>', 'I hope this one will do better than your "Life Returns!" entry. Good luck, Delta_6.', '2007-02-22 15:07:00.000000', NULL, 1),
(3394290, 472564, 66597, '<td valign="top">Powerful image. Really good job with the lighting. Scary and effective.</td>', 'Powerful image. Really good job with the lighting. Scary and effective.', '2007-02-22 15:09:44.000000', NULL, 1),
(3394295, 472603, 66597, '<td valign="top">You did a great job with this - you actually brought humor to a tragic scar on our history. May the hat with the eyeholes disappear forever!</td>', 'You did a great job with this - you actually brought humor to a tragic scar on our history. May the hat with the eyeholes disappear forever!', '2007-02-22 15:10:47.000000', NULL, 1),
(3394300, 472445, 66597, '<td valign="top">This is so funny. Love the expressions, relative heights, looks. The whole thing is executed well aside from the contrast, which looks pushed a couple notches too high.</td>', 'This is so funny. Love the expressions, relative heights, looks. The whole thing is executed well aside from the contrast, which looks pushed a couple notches too high.', '2007-02-22 15:12:46.000000', NULL, 1),
(3394304, 472489, 66597, '<td valign="top">What the heck? Who is Amanda Bowen, and why would she be reviled even in death? I don''t understand this one.</td>', 'What the heck? Who is Amanda Bowen, and why would she be reviled even in death? I don''t understand this one.', '2007-02-22 15:14:26.000000', NULL, 1),
