(3394452, 472603, 66267, '<td valign="top">I think not!</td>', 'I think not!', '2007-02-22 16:05:44.000000', NULL, 1),
(3394474, 471805, 62637, '<td valign="top">This image looks very flat, like you simply desaturated to convert to B&amp;W.  I''m sure you could have created a much more contrasty and dramatic image using channel mixer (in CS2) or even something as simple as "filtered BW" in Picasa.</td>', 'This image looks very flat, like you simply desaturated to convert to B&W.  I''m sure you could have created a much more contrasty and dramatic image using channel mixer (in CS2) or even something as simple as "filtered BW" in Picasa.', '2007-02-22 16:18:10.000000', NULL, 1),
(3394478, 472493, 62637, '<td valign="top">Just because you have a reference to "hate" in the title, doesn''t make it an image that has anything to do with hate.</td>', 'Just because you have a reference to "hate" in the title, doesn''t make it an image that has anything to do with hate.', '2007-02-22 16:20:41.000000', NULL, 1),
(3394489, 472444, 62637, '<td valign="top">It doesn''t make sense to me...  what is this?</td>', 'It doesn''t make sense to me...  what is this?', '2007-02-22 16:22:54.000000', NULL, 1),
(3394494, 472456, 62637, '<td valign="top">At first, I thought "dammit its a bird, this has nothing to do with hate!  1!"<br/> <br/>But then I looked at the bird some more... it actually looks pissed off!</td>', 'At first, I thought "dammit its a bird, this has nothing to do with hate!  1!" But then I looked at the bird some more... it actually looks pissed off!', '2007-02-22 16:24:50.000000', NULL, 1),
