INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3394500, 472643, 32345, '<td valign="top">LOL</td>', 'LOL', '2007-02-22 16:26:05.000000', NULL, 1),
(3394502, 471029, 32345, '<td valign="top">DNMC<br/> <br/>Just Kidding... :) Good idea and well executed.</td>', 'DNMC Just Kidding... :) Good idea and well executed.', '2007-02-22 16:26:16.000000', NULL, 1),
(3394506, 472638, 32345, '<td valign="top">Good idea and very well executed. I''m just afraid that you will lose some points because your image is too small.</td>', 'Good idea and very well executed. I''m just afraid that you will lose some points because your image is too small.', '2007-02-22 16:26:51.000000', NULL, 1),
(3394507, 472499, 62637, '<td valign="top">Anyone that seriously wanted to end their life would know that you go ALONG the wrist, not ACROSS it.  This just screams "immature cry for attention."  :-P</td>', 'Anyone that seriously wanted to end their life would know that you go ALONG the wrist, not ACROSS it.  This just screams "immature cry for attention."  :-P', '2007-02-22 16:26:58.000000', NULL, 1),
(3394509, 472356, 32345, '<td valign="top">So do I, but you do have a lot more snow than we do in my town.</td>', 'So do I, but you do have a lot more snow than we do in my town.', '2007-02-22 16:27:17.000000', NULL, 1),
(3394513, 472712, 62637, '<td valign="top">I don''t understand why you rotated this.  Doesn''t add anything to the image, IMO.</td>', 'I don''t understand why you rotated this.  Doesn''t add anything to the image, IMO.', '2007-02-22 16:28:15.000000', NULL, 1),
(3394520, 471488, 62637, '<td valign="top">YARD SALE!  <br/> <br/>Good capture, one of the reasons I always wear a helmet.  I only hit my head when I''m not paying attention on mellow terrain like this...</td>', 'YARD SALE!   Good capture, one of the reasons I always wear a helmet.  I only hit my head when I''m not paying attention on mellow terrain like this...', '2007-02-22 16:30:01.000000', NULL, 1),
(3394552, 469711, 62637, '<td valign="top">Powerful image, but the low quality and small size detract from the overall impact.  Drop me a PM or search the forums for advice on how to fix that.</td>', 'Powerful image, but the low quality and small size detract from the overall impact.  Drop me a PM or search the forums for advice on how to fix that.', '2007-02-22 16:40:01.000000', NULL, 1),
(3394580, 472489, 62637, '<td valign="top">Who''s Amanda Bowen, and what does she have to do with hate?</td>', 'Who''s Amanda Bowen, and what does she have to do with hate?', '2007-02-22 16:47:33.000000', NULL, 1),
(3394581, 470421, 62637, '<td valign="top">Creepy!</td>', 'Creepy!', '2007-02-22 16:47:45.000000', NULL, 1),
(3394585, 469312, 62637, '<td valign="top">Your spelling and grammar makes me cringe.  Good photo, though.</td>', 'Your spelling and grammar makes me cringe.  Good photo, though.', '2007-02-22 16:48:44.000000', NULL, 1),
(3394590, 471362, 68797, '<td valign="top">This is such a strong photo to me. My little brother hung himself when he was 29. Just 6 years ago. it''s very confronting, but I understood why he did it. I can relate to this picture, eventhough it touches some cords I''d rather not want to be touched. I know how he hated himself and saw this as the only way out. The only 10 I gave out in this challenge.</td>', 'This is such a strong photo to me. My little brother hung himself when he was 29. Just 6 years ago. it''s very confronting, but I understood why he did it. I can relate to this picture, eventhough it touches some cords I''d rather not want to be touched. I know how he hated himself and saw this as the only way out. The only 10 I gave out in this challenge.', '2007-02-22 16:50:18.000000', NULL, 1),
(3394599, 470832, 62637, '<td valign="top">This would have been better without the bizzare processing.</td>', 'This would have been better without the bizzare processing.', '2007-02-22 16:52:05.000000', NULL, 1),
(3394613, 471777, 62637, '<td valign="top">Rook?</td>', 'Rook?', '2007-02-22 16:55:28.000000', NULL, 1),
(3394621, 472020, 62637, '<td valign="top">But I love the cold!</td>', 'But I love the cold!', '2007-02-22 16:56:52.000000', NULL, 1),
(3394638, 469959, 62637, '<td valign="top">You hate dead people?</td>', 'You hate dead people?', '2007-02-22 17:00:01.000000', NULL, 1),
(3394646, 472356, 62637, '<td valign="top">Wow, that looks awesome.  Sorry, no high marks from me, I love snow! Good photo though... I''m sure most people will agree with you, so no low marks either :-P</td>', 'Wow, that looks awesome.  Sorry, no high marks from me, I love snow! Good photo though... I''m sure most people will agree with you, so no low marks either :-P', '2007-02-22 17:02:05.000000', NULL, 1),
(3394656, 469473, 62637, '<td valign="top">Waist deep powder!  How can you hate that?</td>', 'Waist deep powder!  How can you hate that?', '2007-02-22 17:04:04.000000', NULL, 1),
(3394659, 471777, 73601, '<td valign="top">what?</td>', 'what?', '2007-02-22 17:05:02.000000', NULL, 1),
(3394738, 472444, 67258, '<td valign="top">Makes sense to me! It used to be a nightmare trying to cross the road to walk the children to school when they were small as it was really dificult to judge the speed of cars - now they all stick to 30 or below, and it has made the road much safer! <br/>As to the technical merits of the photo - I wonder if the focus might have been better on the speed camera itself?  As to the tilted composition, I am unsure - I don''t hate it, but nor am I conviced by it; the same with the selective desaturation - as a rule I dislike its use, but it works reasonably well here - nice touch keeping the belisha beacons yellow, too.  Basically, this is a photo I am ambivalent about - nothing about it makes me want to view it again.  sorry......</td>', 'Makes sense to me! It used to be a nightmare trying to cross the road to walk the children to school when they were small as it was really dificult to judge the speed of cars - now they all stick to 30 or below, and it has made the road much safer! As to the technical merits of the photo - I wonder if the focus might have been better on the speed camera itself?  As to the tilted composition, I am unsure - I don''t hate it, but nor am I conviced by it; the same with the selective desaturation - as a rule I dislike its use, but it works reasonably well here - nice touch keeping the belisha beacons yellow, too.  Basically, this is a photo I am ambivalent about - nothing about it makes me want to view it again.  sorry......', '2007-02-22 17:32:29.000000', NULL, 1),
(3394792, 472444, 5746, '<td valign="top">Photoradar?</td>', 'Photoradar?', '2007-02-22 17:49:58.000000', NULL, 1),
(3394905, 472445, 5746, '<td valign="top">My winner. Their expressions are priceless. 10.</td>', 'My winner. Their expressions are priceless. 10.', '2007-02-22 18:24:32.000000', NULL, 1),
(3394909, 472536, 5746, '<td valign="top">This is wonderful. The look of its eyes is incredible. 9.</td>', 'This is wonderful. The look of its eyes is incredible. 9.', '2007-02-22 18:25:24.000000', NULL, 1),
(3394919, 470994, 45475, '<td valign="top">Great idea, funny :) The post processing is a little hard on the eyes. Most likely what you were going for though, but still....</td>', 'Great idea, funny :) The post processing is a little hard on the eyes. Most likely what you were going for though, but still....', '2007-02-22 18:27:42.000000', NULL, 1),
(3394927, 471362, 15574, '<td valign="top">Brilliant.</td>', 'Brilliant.', '2007-02-22 18:29:25.000000', NULL, 1),
(3394933, 471761, 45475, '<td valign="top">Haven''t I seen you in the love challenge?? :) The motion blur bothers me a little. Nice dof though.</td>', 'Haven''t I seen you in the love challenge?? :) The motion blur bothers me a little. Nice dof though.', '2007-02-22 18:30:28.000000', NULL, 1),
(3394937, 472492, 45475, '<td valign="top">Very very funny! Don''t ya just hate it when that happens? :D</td>', 'Very very funny! Don''t ya just hate it when that happens? :D', '2007-02-22 18:31:21.000000', NULL, 1),
(3394940, 472487, 15574, '<td valign="top">Looks like a capture from a motion picture.</td>', 'Looks like a capture from a motion picture.', '2007-02-22 18:31:54.000000', NULL, 1),
(3394955, 472239, 45475, '<td valign="top">Ok, this is about my 4th time round to visit you. Call me a thickie, but I''m not getting it! :D Leaning over shoulder? Smelling tails? Taking an "ass" shot? LOL... I dunno, but I look forward to reading your details when the challenge is over. Cheers.</td>', 'Ok, this is about my 4th time round to visit you. Call me a thickie, but I''m not getting it! :D Leaning over shoulder? Smelling tails? Taking an "ass" shot? LOL... I dunno, but I look forward to reading your details when the challenge is over. Cheers.', '2007-02-22 18:34:39.000000', NULL, 1),
(3394967, 472701, 45475, '<td valign="top">I think I understand the concept here, but technically, the sky is blown out in some areas and the foreground is underexposed/dark. Interesting vertical crop though.</td>', 'I think I understand the concept here, but technically, the sky is blown out in some areas and the foreground is underexposed/dark. Interesting vertical crop though.', '2007-02-22 18:37:41.000000', NULL, 1),
(3394983, 472664, 68960, '<td valign="top">I love this pic..</td>', 'I love this pic..', '2007-02-22 18:41:08.000000', NULL, 1),
(3394986, 472712, 68960, '<td valign="top">ok</td>', 'ok', '2007-02-22 18:41:17.000000', NULL, 1),
(3394991, 470832, 45475, '<td valign="top">Wow... some way out there colour processing going on. Effective in that it commands attention but at the same time, is so loud that it steals attention away from the actual emotion you''ve captured in the girls expression.</td>', 'Wow... some way out there colour processing going on. Effective in that it commands attention but at the same time, is so loud that it steals attention away from the actual emotion you''ve captured in the girls expression.', '2007-02-22 18:42:09.000000', NULL, 1),
(3394999, 471154, 45475, '<td valign="top">What a cutie pooch! Poor little things, they love us no matter how we torture them with baths. Too bad you missed the mark on the focus though :(</td>', 'What a cutie pooch! Poor little things, they love us no matter how we torture them with baths. Too bad you missed the mark on the focus though :(', '2007-02-22 18:45:01.000000', NULL, 1),
(3395034, 471805, 45475, '<td valign="top">It''s the most awful spectacle when women fight, but oddly enough, we express hatred and venom more vividly than men. Maybe that''s why it''s so awful? Technically, the problems I see here are the intrusive flash used (re the glare off skin, teeth and tongue) and the b&amp;w conversion has the tones looking a little pastey/grey.</td>', 'It''s the most awful spectacle when women fight, but oddly enough, we express hatred and venom more vividly than men. Maybe that''s why it''s so awful? Technically, the problems I see here are the intrusive flash used (re the glare off skin, teeth and tongue) and the b&w conversion has the tones looking a little pastey/grey.', '2007-02-22 18:53:18.000000', NULL, 1),
(3395038, 471399, 45475, '<td valign="top">Great title and colours. Interesting work :)</td>', 'Great title and colours. Interesting work :)', '2007-02-22 18:54:35.000000', NULL, 1),
(3395112, 472581, 68960, '<td valign="top">Very creative</td>', 'Very creative', '2007-02-22 19:18:46.000000', NULL, 1),
(3395118, 472601, 45475, '<td valign="top">Why hide it? Or is the person hiding because they hate having their photo taken? Hmmm... I think maybe getting your model to glare down the camera (possibly through parted fingers even) would have helped here. The flash was way too bright and has caused harsh shadows from the arms. Why not try again sometime, but move further back so that the light is more diffused. :)</td>', 'Why hide it? Or is the person hiding because they hate having their photo taken? Hmmm... I think maybe getting your model to glare down the camera (possibly through parted fingers even) would have helped here. The flash was way too bright and has caused harsh shadows from the arms. Why not try again sometime, but move further back so that the light is more diffused. :)', '2007-02-22 19:19:59.000000', NULL, 1),
(3395120, 470512, 45475, '<td valign="top">Interesting. Would love to know why you''ve gone so dark with processing though.</td>', 'Interesting. Would love to know why you''ve gone so dark with processing though.', '2007-02-22 19:21:16.000000', NULL, 1),
(3395150, 472130, 45475, '<td valign="top">Nicely framed within the cage and great dof, however, I''m not exactly feeling hate from the creature. Actually, I''d say it looks more content than anything else :)</td>', 'Nicely framed within the cage and great dof, however, I''m not exactly feeling hate from the creature. Actually, I''d say it looks more content than anything else :)', '2007-02-22 19:27:57.000000', NULL, 1),
(3395152, 472445, 17423, '<td valign="top">yes, everyone hates having people with lesser equipment around :)</td>', 'yes, everyone hates having people with lesser equipment around :)', '2007-02-22 19:28:44.000000', NULL, 1),
(3395158, 470421, 45475, '<td valign="top">Oh, I dunno... I quite like it. My mother once had a gorgeous wardrobe made out of the stuff :)</td>', 'Oh, I dunno... I quite like it. My mother once had a gorgeous wardrobe made out of the stuff :)', '2007-02-22 19:30:01.000000', NULL, 1),
(3395160, 472445, 36328, '<td valign="top">I recognise this reprobate! This shot is funny as well as a different take on an otherwise stale challenge.<br/> <br/>The posing is great, and I like the fact that the interaction is between these two only - I.E: not with the photographer. This is also really well lit.<br/> <br/>I have a question. If your son(?) is holding that beast, what was this shot taken with? (please say it''s the Barbie!)</td>', 'I recognise this reprobate! This shot is funny as well as a different take on an otherwise stale challenge. The posing is great, and I like the fact that the interaction is between these two only - I.E: not with the photographer. This is also really well lit. I have a question. If your son(?) is holding that beast, what was this shot taken with? (please say it''s the Barbie!)', '2007-02-22 19:30:57.000000', NULL, 1),
(3395169, 472456, 45475, '<td valign="top">Nasty folk those bird paparazzi ;) Unfortunate about the focus/motion blur issue. With birds, I think you really need to nail the eyes or it doesn''t work.</td>', 'Nasty folk those bird paparazzi ;) Unfortunate about the focus/motion blur issue. With birds, I think you really need to nail the eyes or it doesn''t work.', '2007-02-22 19:33:16.000000', NULL, 1),
