(3413152, 472497, 11854, '<td valign="top">Yep, I hate snow too!</td>', 'Yep, I hate snow too!', '2007-02-28 09:52:30.000000', NULL, 0),
(3413161, 470421, 11854, '<td valign="top">I think what might have hurt you in this, is too many people recognised it from a recent challenge. Also, the face is more easily recognized from the thumbnail than it is when you open it full size. And, some people just LOVE the devil, lol!</td>', 'I think what might have hurt you in this, is too many people recognised it from a recent challenge. Also, the face is more easily recognized from the thumbnail than it is when you open it full size. And, some people just LOVE the devil, lol!', '2007-02-28 09:54:30.000000', NULL, 0),
(3413170, 471362, 32767, '<td valign="top">This is a great image on all fronts. well done and congrats on the ribbon.</td>', 'This is a great image on all fronts. well done and congrats on the ribbon.', '2007-02-28 09:57:09.000000', NULL, 0),
(3413177, 472536, 24454, '<td valign="top">Ohmygosh!  This is absolutely PRECIOUS!!!!!!!  Maddux reminds me of my Milly, she''s part Dachshund, and the sad, but oh-so-loyal and obedient look in Maddux''s eyes remind me so much of her.   I LOVE this photo.  I want it to be a ribbon winner :(<br/> <br/>I''ll just have to add it to my favorites :)<br/> <br/></td>', 'Ohmygosh!  This is absolutely PRECIOUS!!!!!!!  Maddux reminds me of my Milly, she''s part Dachshund, and the sad, but oh-so-loyal and obedient look in Maddux''s eyes remind me so much of her.   I LOVE this photo.  I want it to be a ribbon winner :( I''ll just have to add it to my favorites :) ', '2007-02-28 09:58:58.000000', NULL, 0),
(3413194, 472627, 11854, '<td valign="top">Beautiful image! Of course it''s only DNMC to people who "don''t understand". Hate is a personal feeling. It''s not a universal feeling for all. I feel your hate sista!! LOL!</td>', 'Beautiful image! Of course it''s only DNMC to people who "don''t understand". Hate is a personal feeling. It''s not a universal feeling for all. I feel your hate sista!! LOL!', '2007-02-28 10:02:37.000000', NULL, 0);
